import re,sys
def inline(s):
    s=re.sub(r'\\f[BIRP]','',s)
    s=re.sub(r'\\f\(..','',s)
    s=s.replace('\\-','-').replace('\\&','').replace('\\:','').replace('\\|','').replace('\\^','')
    s=s.replace('\\e','\\').replace('\\ ',' ').replace('\\0',' ')
    s=re.sub(r'\\\*\(..','',s)
    s=s.replace('\\(aq',"'").replace('\\(dq','"').replace('\\(bu','*').replace('\\(mu','x')
    s=s.replace('\\(->','->').replace('\\(<-','<-').replace('\\(pl','+').replace('\\(mi','-')
    s=re.sub(r'\\\(..','?',s)
    s=re.sub(r'\\%','',s)
    s=s.replace('\\\\','\\')
    return s
def unq(args):
    out=[];cur='';inq=False;i=0
    while i<len(args):
        c=args[i]
        if c=='"':
            inq=not inq
        elif c==' ' and not inq:
            if cur: out.append(cur); cur=''
        else: cur+=c
        i+=1
    if cur: out.append(cur)
    return out
for line in open(sys.argv[1],encoding='utf-8',errors='replace'):
    line=line.rstrip('\n')
    if line.startswith('.\\"') or line.strip()=='': 
        print('')
        continue
    if line.startswith('.'):
        m=re.match(r'\.(\S+)\s*(.*)$',line)
        mac=m.group(1); rest=m.group(2)
        if mac in ('SH','SS'):
            print('\n=== '+inline(rest).strip('"')+' ===')
        elif mac in ('B','I','SM'):
            print(inline(rest),end=' ')
        elif mac in ('BR','IR','RB','RI','IB','BI'):
            print(''.join(unq(inline(rest))),end=' ')
        elif mac in ('TP','PP','LP','P','br','sp','IP','HP'):
            print('')
        elif mac in ('nf','fi','ta','ne','ad','na','in','RS','RE','ll','ps','vs','if','el','ie','de','.','TH','hy','nh'):
            pass
        else:
            pass
    else:
        print(inline(line))
EOF
cd /tmp/t && for f in sox soxi soxformat libsox; do python3 deroff.py /workspace/$f.1 > $f.txt 2>/dev/null || python3 deroff.py /workspace/$f.7 > $f.txt; done; ls -l *.txt; wc -l sox.txt

