void sox_init_encodinginfo(sox_encodinginfo_t *e);

/* ---------------------------------------------------------------- formats */

#define SOX_FILE_NOSTDIO 1
#define SOX_FILE_DEVICE  2
#define SOX_FILE_PHONY   4
#define SOX_FILE_REWIND  8
#define SOX_FILE_BIT_REV 16
#define SOX_FILE_NIB_REV 32
#define SOX_FILE_ENDIAN  64
#define SOX_FILE_ENDBIG  128
