/* Core declarations for the audio processing tool.
 * Written from scratch based on observed behaviour of the reference binary.
 */
#ifndef SOX_H_INCLUDED
#define SOX_H_INCLUDED

#include <stdarg.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#ifndef M_PI
#define M_PI 3.14159265358979323846
#endif
#ifndef M_LN10
#define M_LN10 2.30258509299404568402
#endif
#ifndef M_LN2
#define M_LN2 0.69314718055994530942
#endif
#ifndef M_SQRT2
#define M_SQRT2 1.41421356237309504880
#endif

typedef int32_t sox_sample_t;
typedef uint64_t sox_uint64_t;

#define SOX_SAMPLE_PRECISION 32
#define SOX_SAMPLE_MAX ((sox_sample_t)0x7fffffff)
#define SOX_SAMPLE_MIN ((sox_sample_t)(-0x7fffffff - 1))
#define SOX_UNSPEC 0
#define SOX_IGNORE_LENGTH ((sox_uint64_t)-1)
#define SOX_SIZE_MAX ((size_t)-1)

typedef int sox_bool;
#define sox_false 0
#define sox_true 1

/* ---------------------------------------------------------------- macros */

extern size_t sox_clips;  /* not used directly; each site has own counter */

#define SOX_INT_MAX(bits) (INT32_MAX >> (32 - (bits)))
#define SOX_INT_MIN(bits) (-1 - SOX_INT_MAX(bits))
#define SOX_UINT_MAX(bits) (SOX_INT_MAX(bits) * 2u + 1)

/* conversions to internal sample */
#define SOX_SIGNED_8BIT_TO_SAMPLE(d, clips) ((sox_sample_t)(d) << 24)
#define SOX_UNSIGNED_8BIT_TO_SAMPLE(d, clips) \
    (((sox_sample_t)(d) ^ 0x80) << 24)
#define SOX_SIGNED_16BIT_TO_SAMPLE(d, clips) ((sox_sample_t)(d) << 16)
#define SOX_UNSIGNED_16BIT_TO_SAMPLE(d, clips) \
    (((sox_sample_t)(d) ^ 0x8000) << 16)
#define SOX_SIGNED_24BIT_TO_SAMPLE(d, clips) ((sox_sample_t)(d) << 8)
#define SOX_UNSIGNED_24BIT_TO_SAMPLE(d, clips) \
    (((sox_sample_t)(d) ^ 0x800000) << 8)
#define SOX_SIGNED_32BIT_TO_SAMPLE(d, clips) ((sox_sample_t)(d))
#define SOX_UNSIGNED_32BIT_TO_SAMPLE(d, clips) \
    ((sox_sample_t)((uint32_t)(d) ^ 0x80000000u))

sox_sample_t sox_flt_to_sample(double d, size_t *clips);

#define SOX_FLOAT_32BIT_TO_SAMPLE(d, clips) sox_flt_to_sample((double)(d), clips)
#define SOX_FLOAT_64BIT_TO_SAMPLE(d, clips) sox_flt_to_sample((double)(d), clips)

/* conversions from internal sample */
#define SOX_SAMPLE_TO_SIGNED(bits, d, clips) \
    sox_sample_to_signed(bits, d, &(clips))
#define SOX_SAMPLE_TO_UNSIGNED(bits, d, clips) \
    sox_sample_to_unsigned(bits, d, &(clips))

int32_t sox_sample_to_signed(unsigned bits, sox_sample_t d, size_t *clips);
uint32_t sox_sample_to_unsigned(unsigned bits, sox_sample_t d, size_t *clips);

#define SOX_SAMPLE_TO_FLOAT_32BIT(d, clips) \
    ((float)((d) * (1.0 / (SOX_SAMPLE_MAX + 1.0))))
#define SOX_SAMPLE_TO_FLOAT_64BIT(d, clips) \
    ((d) * (1.0 / (SOX_SAMPLE_MAX + 1.0)))

#define SOX_ROUND_CLIP_COUNT(d, clips) \
    ((d) < 0 ? (d) <= SOX_SAMPLE_MIN - 0.5 ? ++(clips), SOX_SAMPLE_MIN \
                                           : (sox_sample_t)((d) - 0.5) \
             : (d) >= SOX_SAMPLE_MAX + 0.5 ? ++(clips), SOX_SAMPLE_MAX \
                                           : (sox_sample_t)((d) + 0.5))

#define SOX_CLIP_COUNT(d, clips) \
    ((d) < SOX_SAMPLE_MIN ? ++(clips), SOX_SAMPLE_MIN \
                          : (d) > SOX_SAMPLE_MAX ? ++(clips), SOX_SAMPLE_MAX \
                                                 : (d))

