{
  char *p = rotbuf();
  double a = fabs(number);
  int prec = a < 9.995 ? 2 : a < 99.95 ? 1 : 0;
  sprintf(p, "%.*f", prec, number);
  return p;
}

/* 3 significant figures with SI suffix; trailing zeros stripped when the
 * value needs no suffix. */
char const *lsx_sigfigs3s(double number)
{
  static char const suffix[] = " kMGTPE";
  char *p = rotbuf();
  int k = 0;
  double a = fabs(number);
  while (a >= 999.5 && k < 6) { number /= 1000, a /= 1000, ++k; }
  if (!k) {
    int prec = a < 9.995 ? 2 : a < 99.95 ? 1 : 0;
    sprintf(p, "%.*f", prec, number);
    if (strchr(p, '.')) {
      char *q = p + strlen(p) - 1;
      while (*q == '0') *q-- = '\0';
      if (*q == '.') *q = '\0';
    }
  } else {
    int prec = a < 9.995 ? 2 : a < 99.95 ? 1 : 0;
    sprintf(p, "%.*f%c", prec, number, suffix[k]);
  }
  return p;
}

char const *str_time(double duration)
{
  char *p = rotbuf();
  int mins = (int)(duration / 60);
  int hours = mins / 60;
  duration -= mins * 60.0;
  mins -= hours * 60;
  sprintf(p, "%02i:%02i:%05.2f", hours, mins, duration);
  return p;
}

char const *size_and_bitrate(sox_format_t *ft, char const **text)
{
  struct stat st;
  double size;
  if (!ft->filename || fstat(fileno(ft->fp), &st) != 0 || !S_ISREG(st.st_mode))
    return NULL;
  size = (double)st.st_size;
  if (text) {
    double secs = ft->signal.length && ft->signal.rate && ft->signal.channels ?
        (double)ft->signal.length / ft->signal.channels / ft->signal.rate : 0;
    *text = secs > 0 ? lsx_sigfigs3s(8.0 * size / secs) : NULL;
  }
  return lsx_sigfigs3s(size);
}

/* ---------------------------------------------------------------- parsing */

/* Note names: C D E F G A B with optional #/b and octave number. */
static int const notes[] = {-9, -7, -5, -4, -2, 0, 2};

int lsx_parse_note(char const *text, char **end_ptr)
{
  int result = INT_MAX;
  if (*text >= 'A' && *text <= 'G') {
    result = notes[*text++ - 'A'];
    while (*text == 'b' || *text == '#')
      result += *text++ == 'b' ? -1 : 1;
    if (isdigit((unsigned char)*text) || (*text == '-' &&
        isdigit((unsigned char)text[1]))) {
      char *e;
      long oct = strtol(text, &e, 10);
      text = e;
      result += (int)((oct - 4) * 12);
    }
  }
  *end_ptr = (char *)text;
  return result;
}

/* Frequency in Hz; a leading % means semitones relative to A440; a note
 * name may also be used.  Trailing k multiplies by 1000. */
double lsx_parse_frequency_k(char const *text, char **end_ptr, int key)
{
  double result;
  if (*text == '%') {
    result = strtod(text + 1, end_ptr);
    if (*end_ptr == text + 1) { *end_ptr = (char *)text; return -1; }
  } else {
    char *e;
    int n = lsx_parse_note(text, &e);
    if (n != INT_MAX) {
      *end_ptr = e;
      result = n;
    } else {
      result = strtod(text, end_ptr);
      if (*end_ptr == text) return -1;
      if (**end_ptr == 'k') { ++*end_ptr; result *= 1000; }
      return result;
    }
  }
  if (key != INT_MAX) {   /* just intonation */
    static const double n[] = {1, 16./15, 9./8, 6./5, 5./4, 4./3, 45./32,
        3./2, 8./5, 5./3, 9./5, 15./8};
    int i = (int)floor(result) - key;
    int oct = (int)floor(i / 12.0);
    i -= oct * 12;
    return 440 * pow(2, key / 12.0) * pow(2, oct) * n[i];
  }
  return 440 * pow(2., result / 12);
}

/* Parse a time specification of the form [[hh:]mm:]ss[.frac][t] or Ns,
 * possibly chained with + and -.  Returns seconds; sample counts are
 * flagged by returning a negative marker (handled by caller). */
static sox_bool parse_time_1(char const **pp, double *seconds,
                             sox_bool *is_samples)
{
  char const *text = *pp;
  double t = 0;
  int i;
  char *end;
  double vals[3];
  int nvals = 0;
  sox_bool got = sox_false;

  *is_samples = sox_false;
  /* count colons */
  {
    char const *p = text;
    double v;
    for (;;) {
      if (*p == ':') { v = 0; ++p; }
      else {
        v = strtod(p, &end);
        if (end == p) {
          if (nvals == 0) return sox_false;
          break;
        }
        got = sox_true;
        p = end;
        if (*p == ':') ++p;
        else { if (nvals < 3) vals[nvals++] = v; break; }
      }
      if (nvals < 3) vals[nvals++] = v;
      else return sox_false;
      continue;
    }
    if (nvals && *p != ':' && v != v) return sox_false;
    text = p;
  }
  if (!got && nvals == 0) return sox_false;
  for (i = 0; i < nvals; i++)
    t = t * 60 + vals[i];
  if (nvals == 1) {
    if (*text == 's' || *text == 'S') { *is_samples = sox_true; ++text; }
    else if (*text == 't' || *text == 'T') ++text;
  } else if (*text == 't' || *text == 'T') ++text;
  *seconds = t;
  *pp = text;
  return sox_true;
}

/* Parse a (possibly chained) time spec, all in seconds. */
sox_bool lsx_parse_time(char const *text, double *seconds)
{
  double total = 0, v;
  sox_bool samples;
  int sign = 1;
  char const *p = text;
  for (;;) {
    if (!parse_time_1(&p, &v, &samples) || samples)
      return sox_false;
    total += sign * v;
    if (*p == '+') { sign = 1; ++p; }
    else if (*p == '-') { sign = -1; ++p; }
    else break;
  }
  if (*p) return sox_false;
  *seconds = total;
  return sox_true;
}

/* Parse a position: [=|+|-]timespec chained.  Result in samples/channel. */
sox_uint64_t lsx_parse_position(double rate, char const *text, char **end_ptr,
    sox_uint64_t latest, sox_uint64_t last, char const *def_relative)
{
  double d;
  sox_bool samples;
  char const *p = text;
  sox_uint64_t base = 0;
  double total = 0;
  int sign = 1;
  char rel = *def_relative;

  if (*p == '=' || *p == '+' || *p == '-') rel = *p++;
  for (;;) {
    if (!parse_time_1(&p, &d, &samples)) {
      if (end_ptr) *end_ptr = (char *)text;
      return 0;
    }
    total += sign * (samples ? d : d * rate);
    if (*p == '+') { sign = 1; ++p; }
    else if (*p == '-') { sign = -1; ++p; }
    else break;
  }
  if (end_ptr) *end_ptr = (char *)p;
  switch (rel) {
    case '=': base = 0; break;
    case '+': base = latest; break;
    case '-': base = last; total = -total; break;
  }
  {
    double r = (double)base + total;
    if (r < 0) r = 0;
    return (sox_uint64_t)(r + 0.5);
  }
}

/* --------------------------------------------------------------- wave gen */

void lsx_generate_wave_table(enum lsx_wave_t type, char data_type,
    void *table, size_t table_size, double min, double max, double phase)
{
  uint32_t t;
  uint32_t phase_offset = (uint32_t)(phase / M_PI / 2 * table_size + 0.5);
  for (t = 0; t < table_size; t++) {
    uint32_t point = (t + phase_offset) % table_size;
    double d;
    switch (type) {
      case SOX_WAVE_SINE:
        d = (sin((double)point / table_size * 2 * M_PI) + 1) / 2;
        break;
      case SOX_WAVE_TRIANGLE:
        d = (double)point * 2 / table_size;
        switch (4 * point / table_size) {
          case 0:         d = d + 0.5; break;
          case 1: case 2: d = 1.5 - d; break;
          case 3:         d = d - 1.5; break;
        }
        break;
      default: d = 0; break;
    }
    d = d * (max - min) + min;
    switch (data_type) {
      case 'f': ((float *)table)[t] = (float)d; break;
      case 'd': ((double *)table)[t] = d; break;
      case 'i': {
        double j = d < 0 ? d - 0.5 : d + 0.5;
        ((int *)table)[t] = (int)j;
        break;
      }
    }
  }
}

double lsx_bessel_I_0(double x)
{
  double term = 1, sum = 1, last_sum, x2 = x / 2;
  int i = 1;
  do {
    double y = x2 / i++;
    last_sum = sum;
    sum += term *= y * y;
  } while (sum != last_sum);
  return sum;
}

/* ---------------------------------------------------------------- getopt */

void lsx_getopt_init(int argc, char *const argv[], char const *shortopts,
                     lsx_getopt_t *state)
{
  state->argc = argc;
  state->argv = argv;
  state->shortopts = shortopts;
  state->ind = 1;
  state->curpos = 1;
  state->opt = 0;
  state->arg = NULL;
}

int lsx_getopt(lsx_getopt_t *state)
{
  char const *p;
  char c;
  if (state->ind >= state->argc) return -1;
  if (state->argv[state->ind][0] != '-' || !state->argv[state->ind][1])
    return -1;
  if (!strcmp(state->argv[state->ind], "--")) { state->ind++; return -1; }
  c = state->argv[state->ind][state->curpos];
  p = strchr(state->shortopts, c);
  if (!p || c == ':') {
    lsx_fail("unknown option `-%c'", c);
    state->ind++;
    state->curpos = 1;
    return '?';
  }
  state->opt = c;
  if (p[1] == ':') {
    if (state->argv[state->ind][state->curpos + 1]) {
      state->arg = (char *)state->argv[state->ind] + state->curpos + 1;
      state->ind++;
      state->curpos = 1;
    } else if (state->ind + 1 < state->argc) {
      state->arg = (char *)state->argv[state->ind + 1];
      state->ind += 2;
      state->curpos = 1;
    } else {
      lsx_fail("option `-%c' requires an argument", c);
      state->ind++;
      return '?';
    }
  } else {
    state->arg = NULL;
    if (state->argv[state->ind][state->curpos + 1])
      state->curpos++;
    else { state->ind++; state->curpos = 1; }
  }
  return c;
}

lsx_enum_item const *lsx_find_enum_text(char const *text,
    lsx_enum_item const *enum_items, int flags)
{
  lsx_enum_item const *result = NULL;
  size_t len = strlen(text);
  sox_bool found = sox_false;
  if (!len) return NULL;
  while (enum_items->text) {
    if (!(flags & LSX_STRINGS_ONLY) && !lsx_strcasecmp(text, enum_items->text))
      return enum_items;
    if (!lsx_strncasecmp(text, enum_items->text, len)) {
      if (strlen(enum_items->text) == len) return enum_items;
      if (found) return NULL;   /* ambiguous */
      result = enum_items;
      found = sox_true;
    }
    ++enum_items;
  }
  return result;
}

lsx_enum_item const *lsx_find_enum_value(unsigned value,
    lsx_enum_item const *enum_items)
{
  for (; enum_items->text; ++enum_items)
    if (enum_items->value == value) return enum_items;
  return NULL;
}

int lsx_enum_option(int c, char const *arg, lsx_enum_item const *items)
{
  lsx_enum_item const *p = lsx_find_enum_text(arg, items, 0);
  if (!p) {
    size_t len = 1;
    char *set = lsx_malloc(len);
    *set = 0;
    for (p = items; p->text; ++p) {
      set = lsx_realloc(set, len += strlen(p->text) + 2);
      strcat(set, ", "); strcat(set, p->text);
    }
    lsx_fail("-%c: `%s' is not one of: %s.", c, arg, set + 2);
    free(set);
    return INT_MAX;
  }
  return (int)p->value;
}

/* ---------------------------------------------------------------- random */

void lsx_set_seed(uint32_t s) { sox_globals.ranqd1 = (int32_t)s; }

uint32_t lsx_random32(void)
{
  sox_globals.ranqd1 = (int32_t)((uint32_t)1664525 *
      (uint32_t)sox_globals.ranqd1 + (uint32_t)1013904223);
  return (uint32_t)sox_globals.ranqd1;
}
